"""Make generated report conclusions match the current measured series."""
import json
import re
import statistics
from pathlib import Path

def polish(text, out):
    def read(name):
        path=out/name
        return json.loads(path.read_text(encoding='utf-8-sig')) if path.exists() else None
    # Blank lines between rows break GitHub Markdown tables.
    text=re.sub(r'(?m)(^\|[^\n]*\|)\n(?:[ \t]*\n)+(?=\|)',r'\1\n',text)
    text=text.replace('# Проєктування сервісу вакцинацій','### Проєктування сервісу вакцинацій')
    text=text.replace('Локальний журнал тестів: results/local-tests.txt.',
                      'Окрема перевірка виправлень: correction-checks.txt (11 тестів; це не журнал Docker-серії).')
    machine=read('machine.json')
    if machine:
        pattern=r'Процеси — за кількістю ядер.*?Для кожного рівня'
        info=f"У цій серії хост має {machine['cores']} логічних ядер; генератор використовував {machine['generator_processes'] or machine['cores']} процесів і {machine['generator_threads']} потоків на процес. Генератор і Docker працювали на одному хості. Для кожного рівня"
        text=re.sub(pattern,info,text)
    text=text.replace('`python scripts/experiment.py --reset-lab-data`',
                      '`python -X utf8 scripts/experiment.py --reset-lab-data --threads 512`')
    runs={}
    for n in (1,2):
        for rate in (10,100,500):
            values=[read(f'open-{n}-{rate}-{i}.json') for i in (1,2,3)]
            if all(values): runs[n,rate]=values
    series=read('series.json')
    reviewed_snapshot=bool(series and series.get('image_id')=='sha256:19bcb20831d41b6e768f652519b3481d0e25079b675a6ea64f02881d24a3b415')
    all_valid=bool(reviewed_snapshot and len(runs)==6 and all(v['summary'].get('valid_open_loop',False) for vs in runs.values() for v in vs))
    if all_valid:
        text=re.sub(r'Планувальник подає завдання строго.*?(?=\n\s*### Перевірка генератора)',
            'Усі 18 основних прогонів пройшли контроль відправки: фактична швидкість не нижча за 98% цілі, а p95 затримки відправки не перевищує 100 мс. На 500 rps медіани фактичної відправки — 499.800 rps для однієї репліки та 499.767 rps для двох. Отже, попереднє обмеження пулу генератора в цій серії не спостерігається за цими критеріями. Планове й фактичне відправлення відрізняються на десятки мілісекунд; черга не є буквально нульовою. Критерій застосовується до часу запуску HTTP-запиту на клієнті, а не до окремо виміряного моменту прибуття на сервер.\n\n',text,flags=re.S)
        table=['### Успішна пропускна здатність і розкид повторів','',
               'Основна achieved_rps рахує всі завершені спроби у 30-секундному вікні, включно з транспортними помилками (status=0). Тому це не швидкість успішних HTTP-відповідей. Нижче success_rps рахує тільки відповіді 2xx у тому самому вікні. Частка неуспіху в основній таблиці охоплює всі заплановані запити, зокрема завершені після вікна.','',
               '| Репліки | Ціль rps | Медіана 2xx rps | Діапазон achieved_rps | Діапазон неуспіхів, % |',
               '|---|---|---|---|---|']
        for (n,rate),vs in runs.items():
            ss=[v['summary'] for v in vs]
            a=[s['achieved_rps'] for s in ss];e=[100*s['non_2xx_fraction'] for s in ss]
            table.append(f"| {n} | {rate} | {statistics.median(s['success_rps'] for s in ss):.3f} | {min(a):.3f}–{max(a):.3f} | {min(e):.3f}–{max(e):.3f} |")
        table+=['','На 500 rps для однієї репліки медіанна частка неуспіхів — 61.220%, для двох — 7.667%. У сирих даних є TimeoutError, RemoteDisconnected та окремі HTTP 500/504; у третьому прогоні однієї репліки також зафіксовано дві помилки Windows 10048. Без логів вебпроцесу, часових ресурсних вимірювань і окремого хоста генератора конкретне вузьке місце не встановлено. Спільними залишаються PostgreSQL, Nginx та ресурси хоста. Високі помилки під перевантаженням не підмінюються успішними відповідями.','']
        text=text.replace('## Етап 7 Розрахунки','\n'.join(table)+'\n## Етап 7 Розрахунки')
        caveat='Значення S та e вище обчислено за achieved_rps, тобто швидкістю завершення всіх спроб. Через різну частку помилок на 500 rps вони не є чистою оцінкою прискорення успішного обслуговування і не визначають буквальну частку послідовного коду. Для 2xx медіани становлять 168.633 та 402.433 rps; їх відношення приблизно 2.386. Це описове порівняння за даними серії, а не доказ суперлінійного прискорення: три повтори двох реплік суттєво різняться.\n\n'
        text=text.replace('### Закон Літтла',caveat+'### Закон Літтла')
        closed=read('closed.json')
        if closed and 'open_reference' in closed:
            o,c=closed['open_reference'],closed['summary']
            explanation=f"У фактичній серії p95 закритого контуру ({c['p95_ms']:.3f} мс) {'вищий' if c['p95_ms']>=o['p95_ms'] else 'нижчий'} за p95 відкритого ({o['p95_ms']:.3f} мс). Тому очікуване зменшення затримки {'не підтверджено' if c['p95_ms']>=o['p95_ms'] else 'спостерігається'}. Закритий прогін створено з {closed['concurrency']} одночасними потоками: round({o['measured_L']:.7f}). Фактичні 2xx: відкритий {o['success_rps']:.3f} rps, закритий {c['success_rps']:.3f} rps. Перцентилі включають помилки й очікування до тайм-ауту 15 с; закритий генератор має один процес із великою кількістю потоків, тому порівняння також залежить від його ресурсів. Теоретично закритий контур стримує наростання черги, але на цих числах не можна стверджувати, що він дав менший p95."
            text=re.sub(r'За перевантаження закритий контур сам.*?(?=\n\s*## Етап 8)',explanation+'\n\n',text,flags=re.S)
        conclusion='На 10 і 100 rps обидві конфігурації утримували потік без неуспішних спроб. На 500 rps генератор продовжував відправляти близько 500 запитів/с, але стенд у частині повторів відповідав із великими затримками та помилками. Для однієї й двох реплік медіанна achieved_rps становила 431.567 і 441.767 (зростання приблизно 2.36%), а медіанна успішна швидкість 2xx — 168.633 і 402.433 rps. Медіанний p95 зменшився з 15015.074 до 7243.417 мс, частка неуспішних спроб — з 61.220% до 7.667%. Друга репліка покращила успішне обслуговування, але на 500 rps результати нестабільні: один із трьох прогонів двох реплік мав 0% помилок, інші — 24.447% та 7.667%. Спільні компоненти й конкуренція за ресурси хоста обмежують інтерпретацію; точний компонент обмеження не доведено. Закон Літтла на 100 rps узгоджується з виміряним L. У закритому контурі менший p95 у цій серії не підтверджено. Додаткова вимога варіанта 7 підтверджена однаковими базовими шарами двох збірок.'
        text=re.sub(r'## Висновок\n.*?(?=\n## Відкинуті рішення)', '## Висновок\n\n'+conclusion+'\n\n',text,flags=re.S)
    text=re.sub(r'На машині експерименту початковий порт 8080.*?8080\.', 'Порт хоста налаштовано як 18080, контейнерний порт Nginx — 8080.', text)
    text=re.sub(r'\n{3,}','\n\n',text)
    return text
